import csv, json, math
from collections import defaultdict
from pathlib import Path
base = Path('/app/data')
with open(base/'config.json') as f:
    cfg=json.load(f)
with open(base/'time_slots.csv', newline='') as f:
    slots=list(csv.DictReader(f))
with open(base/'truck_classes.csv', newline='') as f:
    classes=list(csv.DictReader(f))
with open(base/'yard_blocks.csv', newline='') as f:
    blocks=list(csv.DictReader(f))
with open(base/'class_block_eligibility.csv', newline='') as f:
    elig=list(csv.DictReader(f))
with open(base/'scenarios.csv', newline='') as f:
    scens=list(csv.DictReader(f))
with open(base/'scenario_demand.csv', newline='') as f:
    dem=list(csv.DictReader(f))
with open(base/'scenario_block_capacity.csv', newline='') as f:
    cap=list(csv.DictReader(f))

slot_ids=[r['slot_id'] for r in slots]
slot_idx={r['slot_id']:int(r['slot_index']) for r in slots}
class_ids=[r['class_id'] for r in classes]
block_ids=[r['block_id'] for r in blocks]
allowed={r['class_id']:r['allowed_slots'].split('|') for r in classes}
latest={r['class_id']:int(r['latest_service_slot']) for r in classes}
reefer={r['class_id']:int(r['reefer_flag']) for r in classes}
exposure={r['class_id']:float(r['exposure_units']) for r in classes}
base_gate={r['slot_id']:int(r['base_gate_capacity']) for r in slots}
min_quota={r['slot_id']:int(r['min_quota']) for r in slots}
queue_lim={r['slot_id']:int(r['queue_limit_trucks']) for r in slots}
demdict={(r['scenario_id'],r['slot_id'],r['class_id']):int(r['requested_trucks']) for r in dem}
gmult={r['scenario_id']:float(r['gate_multiplier']) for r in scens}
capacity={(r['scenario_id'],r['slot_id'],r['block_id']):float(r['capacity_multiplier']) for r in cap}
work={(r['class_id'],r['block_id']):float(r['work_units']) for r in elig}
base_work={r['block_id']:float(r['base_work_units']) for r in blocks}
max_teams={r['block_id']:int(r['max_extra_teams']) for r in blocks}
# summarize feasible totals
print('Total min slot quota', sum(min_quota.values()))
print('Quota day bounds', cfg['minimum_total_quota'], cfg['maximum_total_quota'])
for srow in scens:
    s=srow['scenario_id']
    total_gate=sum(math.floor(base_gate[t]*gmult[s]+1e-9) for t in slot_ids)
    total_dem=sum(demdict[s,t,c] for t in slot_ids for c in class_ids)
    print(s,'gate_cap_total',total_gate,'demand_total',total_dem)
print('Eligibility counts by class')
byc=defaultdict(int)
for e in elig: byc[e['class_id']]+=1
print(dict(byc))
# rough capacity upper bounds with max teams
for srow in scens:
    s=srow['scenario_id']
    total=0
    for t in slot_ids:
        for b in block_ids:
            total += base_work[b]*capacity[s,t,b] + cfg['team_work_unit_gain']*max_teams[b]
    print('scenario total work ub',s,round(total,1))
    break
PY"

